#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long MOD = 1000000007LL;
    int n, amount;
    cin >> n >> amount;
    vector<long long> f(amount + 1, 0);
    f[0] = 1;
    for (int i = 0; i < n; i++) {
        int c;
        cin >> c;
        for (int a = c; a <= amount; a++) f[a] = (f[a] + f[a - c]) % MOD;
    }
    cout << f[amount] << '\n';
    return 0;
}

